package com.verchasel.specsound;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.PluginPanel;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.event.ChangeEvent;
import javax.swing.filechooser.FileNameExtensionFilter;
import java.awt.*;
import java.io.File;
import java.util.function.Function;

import static com.verchasel.specsound.SpecSoundPlugin.*;

public class SpecSoundPanel extends PluginPanel
{
    private final ConfigManager configManager;

    private final JCheckBox useBundledCheck;
    private JButton chooseBtn = null;
    private JLabel pathLabel = null;
    private final JSlider volumeSlider;
    private final JLabel volumeValue;

    public SpecSoundPanel(ConfigManager configManager, Runnable testAction)
    {
        this.configManager = configManager;

        setLayout(new BorderLayout());
        JPanel col = new JPanel();
        col.setLayout(new BoxLayout(col, BoxLayout.Y_AXIS));
        col.setBorder(new EmptyBorder(12, 12, 16, 12));
        add(col, BorderLayout.CENTER);

        Function<JComponent, JPanel> row = comp -> {
            JPanel p = new JPanel(new FlowLayout(FlowLayout.CENTER, 8, 0));
            p.setBorder(new EmptyBorder(0, 0, 10, 0));
            p.add(comp);
            return p;
        };
        Function<JComponent[], JPanel> rowMany = comps -> {
            JPanel p = new JPanel(new FlowLayout(FlowLayout.CENTER, 8, 0));
            p.setBorder(new EmptyBorder(0, 0, 10, 0));
            for (JComponent c : comps) p.add(c);
            return p;
        };

        useBundledCheck = new JCheckBox("Use bundled sound");
        useBundledCheck.addActionListener(e -> {
            boolean val = useBundledCheck.isSelected();
            setCfg(K_USE_BUNDLED, val);
            if (val) {
                setCfg(K_CUSTOM_PATH, "");
                pathLabel.setText("(no file selected)");
                chooseBtn.setEnabled(false);
            } else {
                chooseBtn.setEnabled(true);
            }
        });
        col.add(row.apply(useBundledCheck));

        chooseBtn = new JButton("Choose custom WAV…");
        chooseBtn.addActionListener(e -> {
            JFileChooser fc = new JFileChooser();
            fc.setDialogTitle("Select a WAV file");
            fc.setFileFilter(new FileNameExtensionFilter("WAV files", "wav", "wave"));
            if (fc.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
                File f = fc.getSelectedFile();
                if (f != null) {
                    setCfg(K_CUSTOM_PATH, f.getAbsolutePath());
                    setCfg(K_USE_BUNDLED, false);
                    pathLabel.setText(shorten(f.getAbsolutePath()));
                    useBundledCheck.setSelected(false);
                    chooseBtn.setEnabled(true);
                    JOptionPane.showMessageDialog(this, "Custom sound set.");
                }
            }
        });
        col.add(row.apply(chooseBtn));

        pathLabel = new JLabel("(no file selected)", SwingConstants.CENTER);
        JPanel pathRow = row.apply(pathLabel);
        pathRow.setBorder(new EmptyBorder(0, 0, 14, 0));
        col.add(pathRow);

        JLabel volLabel = new JLabel("Volume");
        volumeSlider = new JSlider(0, 100, 100);
        volumeSlider.setPaintTicks(true);
        volumeSlider.setMajorTickSpacing(25);
        volumeSlider.setMinorTickSpacing(5);
        volumeValue = new JLabel("100%");

        volumeSlider.addChangeListener((ChangeEvent e) -> {
            int val = volumeSlider.getValue();
            volumeValue.setText(val + "%");
            if (!volumeSlider.getValueIsAdjusting()) {
                setCfg(K_VOLUME, val);
            }
        });

        JPanel volRowPanel = rowMany.apply(new JComponent[]{ volLabel, volumeSlider, volumeValue });
        volRowPanel.setBorder(new EmptyBorder(6, 0, 14, 0));
        col.add(volRowPanel);

        JButton testBtn = new JButton("Test sound");
        testBtn.addActionListener(e -> { if (testAction != null) testAction.run(); });
        col.add(row.apply(testBtn));

        refreshFromConfig();
    }

    public void refreshFromConfig()
    {
        boolean useBundled = getBool();
        String path        = getString();
        int vol            = getInt();

        useBundledCheck.setSelected(useBundled);
        chooseBtn.setEnabled(!useBundled);
        pathLabel.setText(shorten(path));
        volumeSlider.setValue(Math.max(0, Math.min(100, vol)));
        volumeValue.setText(volumeSlider.getValue() + "%");
    }

    private void setCfg(String key, Object value)
    {
        configManager.setConfiguration(GROUP, key, value);
    }
    private boolean getBool()
    {
        String s = configManager.getConfiguration(GROUP, K_USE_BUNDLED);
        return (s == null) ? D_USE_BUNDLED : Boolean.parseBoolean(s);
    }
    private int getInt()
    {
        String s = configManager.getConfiguration(GROUP, K_VOLUME);
        if (s == null) return D_VOLUME;
        try { return Integer.parseInt(s); } catch (Exception ignored) { return D_VOLUME; }
    }
    private String getString()
    {
        String s = configManager.getConfiguration(GROUP, K_CUSTOM_PATH);
        return (s == null) ? D_CUSTOM_PATH : s;
    }

    private static String shorten(String s)
    {
        if (s == null || s.isBlank()) return "(no file selected)";
        return s.length() > 60 ? "…" + s.substring(s.length() - 60) : s;
    }
}

package com.verchasel.specsound;

import lombok.extern.slf4j.Slf4j;

import net.runelite.api.Client;
import net.runelite.api.events.GameTick;

import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.swing.SwingUtilities;
import java.awt.image.BufferedImage;
import java.io.File;

@Slf4j
@PluginDescriptor(
        name = "Special Attack Sound",
        description = "Plays one custom WAV when your special-attack energy decreases. In-client file picker and volume—no sound IDs or folders.",
        tags = {"special-attack","spec","audio","sound","sfx","custom"}
)
public class SpecSoundPlugin extends Plugin
{
    private static final int VARP_SPEC_PERCENT = 300;

    static final String GROUP         = "specsound";
    static final String K_USE_BUNDLED = "useBundled";
    static final String K_CUSTOM_PATH = "customPath";
    static final String K_VOLUME      = "volume";

    static final boolean D_USE_BUNDLED = true;
    static final String  D_CUSTOM_PATH = "";
    static final int     D_VOLUME      = 100;

    private int  lastSpecPct = -1;
    private long lastPlayMs  = 0;

    @Inject private Client client;
    @Inject private ClientToolbar clientToolbar;
    @Inject private ConfigManager configManager;
    @Inject private AudioPlayer audioPlayer;
    @Inject private ClientThread clientThread;

    private NavigationButton navButton;
    private SpecSoundPanel panel;

    @Override
    protected void startUp()
    {
        if (configManager.getConfiguration(GROUP, K_USE_BUNDLED) == null)
            configManager.setConfiguration(GROUP, K_USE_BUNDLED, D_USE_BUNDLED);
        if (configManager.getConfiguration(GROUP, K_CUSTOM_PATH) == null)
            configManager.setConfiguration(GROUP, K_CUSTOM_PATH, D_CUSTOM_PATH);
        if (configManager.getConfiguration(GROUP, K_VOLUME) == null)
            configManager.setConfiguration(GROUP, K_VOLUME, D_VOLUME);

        panel = new SpecSoundPanel(configManager, this::playCustomSound);

        BufferedImage icon = ImageUtil.loadImageResource(SpecSoundPlugin.class, "/icons/icon.png");
        navButton = NavigationButton.builder()
                .tooltip("Spec Sound")
                .icon(icon)
                .panel(panel)
                .priority(5)
                .build();
        clientToolbar.addNavigation(navButton);

        clientThread.invoke(() -> {
            lastSpecPct = client.getVarpValue(VARP_SPEC_PERCENT);
            lastPlayMs  = 0;
        });

        SwingUtilities.invokeLater(panel::refreshFromConfig);
    }

    @Override
    protected void shutDown()
    {
        if (navButton != null) clientToolbar.removeNavigation(navButton);
        navButton = null;
        panel = null;

        lastSpecPct = -1;
        lastPlayMs  = 0;
    }

    @Subscribe
    public void onGameTick(GameTick t)
    {
        final int now = client.getVarpValue(VARP_SPEC_PERCENT);

        if (lastSpecPct >= 0 && now < lastSpecPct && System.currentTimeMillis() - lastPlayMs > 250)
        {
            log.debug("Spec drop detected: {} -> {}", lastSpecPct, now);
            playCustomSound();
            lastPlayMs = System.currentTimeMillis();
        }

        lastSpecPct = now;
    }

    void playCustomSound()
    {
        try
        {
            final boolean useBundled = getBool();
            final String path        = getString();
            final float gainDb       = volumeToDb(getInt());

            if (useBundled)
            {
                if (SpecSoundPlugin.class.getResource("/specsound/bundled.wav") == null) {
                    log.warn("Bundled sound missing at /specsound/bundled.wav");
                    return;
                }
                audioPlayer.play(SpecSoundPlugin.class, "/specsound/bundled.wav", gainDb);
            }
            else
            {
                if (path != null && !path.isBlank())
                {
                    final File f = new File(path);
                    if (f.exists() && f.isFile())
                    {
                        audioPlayer.play(f, gainDb);
                        return;
                    }
                    log.info("Custom file missing ({}), falling back to bundled", path);
                }
                if (SpecSoundPlugin.class.getResource("/specsound/bundled.wav") != null) {
                    audioPlayer.play(SpecSoundPlugin.class, "/specsound/bundled.wav", gainDb);
                } else {
                    log.warn("Fallback bundled sound missing at /specsound/bundled.wav");
                }
            }
        }
        catch (Exception ex)
        {
            log.warn("Failed to play custom spec sound", ex);
        }
    }

    boolean getBool() {
        final String s = configManager.getConfiguration(GROUP, SpecSoundPlugin.K_USE_BUNDLED);
        return (s == null) ? SpecSoundPlugin.D_USE_BUNDLED : Boolean.parseBoolean(s);
    }
    int getInt() {
        final String s = configManager.getConfiguration(GROUP, SpecSoundPlugin.K_VOLUME);
        if (s == null) return SpecSoundPlugin.D_VOLUME;
        try { return Integer.parseInt(s); } catch (Exception ignored) { return SpecSoundPlugin.D_VOLUME; }
    }
    String getString() {
        final String s = configManager.getConfiguration(GROUP, SpecSoundPlugin.K_CUSTOM_PATH);
        return (s == null) ? SpecSoundPlugin.D_CUSTOM_PATH : s;
    }

    private static float volumeToDb(int vol0to100)
    {
        int v = Math.max(0, Math.min(100, vol0to100));
        return (v == 0) ? -80f : (float)(20.0 * Math.log10(v / 100.0));
    }
}

package com.verchasel.specsound;

import net.runelite.client.RuneLite;
